where not exists(select 1 from ascent_game.rejected_associations r where (r.clue=x.clue and r.word=x.word) or (r.clue=x.word and r.word=x.clue))
on conflict(clue,word) do update set strength=greatest(ascent_game.association_scores_v7.strength,excluded.strength),reason=excluded.reason
where ascent_game.association_scores_v7.strength<95 or ascent_game.association_scores_v7.reason ~ '^(Related|Associated|A direct association|Direct reverse)' or ascent_game.association_scores_v7.reason like '%↔%';

create or replace function ascent_game.local_association_variants(clues text[],guess text,known jsonb)
returns jsonb language sql stable set search_path to '' as $$
with g as (
 select guess word union
 select f from unnest(ascent_game.guess_forms(guess)) f where not exists(select 1 from ascent_game.wordnet_members m where m.word=guess) union
 select b.word from ascent_game.equivalent_answers a join ascent_game.equivalent_answers b using(group_key) where a.word=guess and a.group_key like 'inflection:%'
), c as (
 select x clue,x term from unnest(clues)x where not known ? x union
 select x,f from unnest(clues)x cross join lateral unnest(ascent_game.guess_forms(x)) f where not known ? x and not exists(select 1 from ascent_game.wordnet_members m where m.word=x) union
 select x,b.word from unnest(clues)x join ascent_game.equivalent_answers a on a.word=x join ascent_game.equivalent_answers b using(group_key) where a.group_key like 'inflection:%' and not known ? x
), hits as (
 select c.clue,s.reason,s.strength,s.word from c join ascent_game.association_scores_v7 s on s.clue=c.term join g on g.word=s.word where s.strength>=90 and not exists(select 1 from ascent_game.rejected_associations r where (r.clue=c.clue and r.word=guess) or (r.clue=s.clue and r.word=s.word))
 union all
 select c.clue,s.reason,s.strength,s.clue from c join ascent_game.association_scores_v7 s on s.word=c.term join g on g.word=s.clue where s.strength>=90 and s.reason not like 'Semantic link via %' and not exists(select 1 from ascent_game.rejected_associations r where (r.clue=c.clue and r.word=guess) or (r.clue=s.clue and r.word=s.word))
), best as (select distinct on(clue) clue,reason from hits order by clue,strength desc,word,reason)
select case when ascent_game.is_displayed_clue(clues,guess) then '{}'::jsonb else known||coalesce((select jsonb_object_agg(clue,reason) from best),'{}'::jsonb) end
$$;
revoke all on function ascent_game.local_association_variants(text[],text,jsonb) from public,anon,authenticated;

CREATE OR REPLACE FUNCTION ascent_game.semantic_complete_guess(clues text[], guess text, ticket uuid, known jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare normalized text; corrected text; missing text[]; more jsonb; result jsonb;
begin
 normalized:=lower(btrim(regexp_replace(regexp_replace(coalesce(guess,''),'[’'']','','g'),'[[:space:]‐‑–—-]+',' ','g')));
 normalized:=btrim(regexp_replace(normalized,'[.!?]+$','','g'));
 if ascent_game.is_displayed_clue(clues,normalized) then return '{}'::jsonb;end if;
 if normalized=any(clues) or (select count(*) from jsonb_object_keys(known))=cardinality(clues) then return ascent_game.filter_rejected_associations(normalized,known);end if;
 corrected:=normalized;
 known:=ascent_game.local_association_variants(clues,normalized,known);
 known:=ascent_game.live_dictionary_links(clues,normalized,ascent_game.knowledge_matches(clues,normalized,known));
 if known='{}'::jsonb then
  corrected:=ascent_game.correct_spelling(normalized);
  if ascent_game.is_displayed_clue(clues,corrected) then return '{}'::jsonb;end if;
  if corrected<>normalized then known:=ascent_game.local_association_variants(clues,corrected,ascent_game.match_guess(7,clues,corrected));end if;
 end if;
 -- Reciprocal high-confidence registered relationships are direct evidence, not similarity guesses.
 known:=known||coalesce((select jsonb_object_agg(s.word,s.reason||' (reciprocal registered relationship)') from ascent_game.association_scores_v7 s where s.clue=corrected and s.word=any(clues) and not known ? s.word and s.strength>=85 and s.reason not like 'Semantic link via %' and not exists(select 1 from ascent_game.rejected_associations r where (r.clue=s.word and r.word=corrected) or (r.clue=corrected and r.word=s.word))),'{}'::jsonb);
 known:=ascent_game.complete_equivalent_answers(clues,corrected,known);
 if corrected<>normalized then known:=ascent_game.live_dictionary_links(clues,corrected,ascent_game.knowledge_matches(clues,corrected,known));end if;
 missing:=array(select c from unnest(clues) c where not known ? c);
 if cardinality(missing)>0 then result:=ascent_game.llm_complete(clues,corrected,ticket,known);else result:=known;end if;
 result:=ascent_game.filter_rejected_associations(corrected,result);
 if corrected<>normalized and result<>'{}'::jsonb then
  select jsonb_object_agg(key,'Interpreted as “'||corrected||'” — '||value) into result from jsonb_each_text(result);
 end if;
 return result;
exception when others then return known;
end;$function$;

CREATE OR REPLACE FUNCTION ascent_game.preview_registered_guess(clues text[], guess text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 with base as (select ascent_game.live_dictionary_links(clues,guess,ascent_game.knowledge_matches(clues,guess,ascent_game.complete_equivalent_answers(clues,guess,ascent_game.local_association_variants(clues,guess,ascent_game.match_guess(7,clues,guess))))) known), v as (select embedding from ascent_game.semantic_word_vectors where word=guess)
 select case when ascent_game.is_displayed_clue(clues,guess) then '{}'::jsonb else ascent_game.filter_rejected_associations(guess,ascent_game.llm_cached_matches(clues,guess,known||coalesce((select ascent_game.vector_clue_matches(array(select c from unnest(clues) c where not known ? c),guess,embedding) from v where (select enabled from ascent_game.semantic_config where singleton)), '{}'::jsonb))) end from base
$function$;
